/* Exhaustive palette-five and palette-six recoloring graphs of Paley(13).
   Run: c++ -O3 -std=c++17 check_recolor.cpp -o checker; ./checker 5; ./checker 6
   The vertex set is Z/13, with edges at nonzero quadratic residues.
   All labels remain fixed and color names are NOT quotiented. */
#include <bits/stdc++.h>
using namespace std;struct DSU{vector<int> p,s;DSU(int n):p(n),s(n,1){iota(p.begin(),p.end(),0);}int F(int a){if(p[a]==a)return a;return p[a]=F(p[a]);}void J(int a,int b){a=F(a);b=F(b);if(a!=b){if(s[a]<s[b])swap(a,b);p[b]=a;s[a]+=s[b];}}};
int main(int argc,char** argv){const int N=13; const int k = argc > 1 ? atoi(argv[1]) : 5; if (k != 5 && k != 6) return 2;int col[N];fill(col,col+N,-1);int adj[N]={0};for(int i=0;i<N;i++)for(int j=0;j<N;j++)if(i!=j){int d=(i-j+N)%N;if(d==1||d==3||d==4||d==9||d==10||d==12)adj[i]|=1<<j;}vector<int> order(N);iota(order.begin(),order.end(),0);vector<unsigned long long> powk(N);powk[0]=1;for(int i=1;i<N;i++)powk[i]=powk[i-1]*k;vector<unsigned long long> states;function<void(int,unsigned long long)> rec=[&](int dep,unsigned long long code){if(dep==N){states.push_back(code);return;}int v=order[dep],mask=0;for(int j=0;j<N;j++)if((adj[v]&(1<<j))&&col[j]>=0)mask|=1<<col[j];for(int c=0;c<k;c++)if(!(mask&(1<<c))){col[v]=c;rec(dep+1,code+c*powk[v]);}col[v]=-1;};rec(0,0);cerr<<"states "<<states.size()<<endl;unordered_map<unsigned long long,int> pos;pos.reserve(states.size()*2);for(int i=0;i<(int)states.size();i++)pos.emplace(states[i],i);DSU d(states.size());map<int,int> degHist;long long E=0;for(int i=0;i<(int)states.size();i++){auto code=states[i];int cs[N];for(int v=0;v<N;v++)cs[v]=(code/powk[v])%k;int deg=0;for(int v=0;v<N;v++){int forbid=0;for(int j=0;j<N;j++)if(adj[v]&(1<<j))forbid|=1<<cs[j];for(int z=0;z<k;z++)if(z!=cs[v]&&!(forbid&(1<<z))){int next=pos.at(code+(z-cs[v])*powk[v]);deg++;if(i<next){E++;d.J(i,next);}}}degHist[deg]++;}
map<int,int> sz,dist;for(int i=0;i<(int)states.size();i++)sz[d.F(i)]++;for(auto [a,b]:sz)dist[b]++;
cout<<"N "<<states.size()<<" E "<<E<<" components "<<sz.size()<<" sizes";for(auto [a,b]:dist)cout<<" "<<a<<":"<<b;cout<<" degrees";for(auto [a,b]:degHist)cout<<" "<<a<<":"<<b;cout<<endl;
}
